algorithms.pseudocode:
Algorithm: BellmanFord(constraints, n)
  x <- [0, 0, ..., 0]
  for k = 1 to n-1:
    for each (src, tgt, w) in constraints:
      if x[src] > x[tgt] + w:
        x[src] <- x[tgt] + w
  for each (src, tgt, w) in constraints:
    if x[src] > x[tgt] + w:
      return INFEASIBLE + negative_cycle
  return FEASIBLE, x

Time: O(n*m), Space: O(n+m)

Algorithm: HellyWitness(constraints, n)
  sys <- constraints
  for each c in constraints:
    if IsFeasible(sys \ {c}) == False:
      sys <- sys \ {c}
  assert |sys| <= n
  return sys

Time: O(m * T_feasibility)
